   "hoc": [
    {
     "ng": "I",
     "ngTen": "Mythic Age · Khai Thiên Lập Địa",
     "id": 2,
     "ten": "Bàn Cổ Khai Thiên Lập Địa",
     "dan": 11,
     "loi": "Bàn Cổ giải quyết câu hỏi mà không nền văn minh nào có thể tránh: *Tại sao vũ trụ có trật tự?* Câu trả lời của Trung Hoa không phải \"Thần linh ra lệnh\" mà là \"Một lực lượng đã hy sinh bản thân để tạo ra trật tự.\" Điều này cắm sâu vào tâm lý văn hóa Trung Hoa một giá trị nền: **sự hy sinh vì cái toàn thể là hành động cao nhất.**"
    },
    {
     "ng": "II",
     "ngTen": "Ngũ Đế · Thời Hoàng Kim Đức Trị",
     "id": 21,
     "ten": "Hoàng Đế — Người Khai Sáng Hoa Hạ",
     "dan": 11,
     "loi": "Ch.021 là **bước chuyển từ thần thoại sang lịch sử**. Sử ký của Tư Mã Thiên — cuốn sử quan trọng nhất Trung Hoa — **bắt đầu bằng Hoàng Đế**, không phải Bàn Cổ hay Nữ Oa. Điều này có nghĩa: với Tư Mã Thiên, Hoàng Đế là điểm đủ \"lịch sử\" để mở đầu chính sử. Mọi thứ trước là thần thoại; từ Hoàng Đế trở đi là lịch sử."
    },
    {
     "ng": "III",
     "ngTen": "Nhà Hạ · Triều Đại Đầu Tiên",
     "id": 61,
     "ten": "Nhà Hạ Có Thật Không? — Một Câu Hỏi Chưa Đóng",
     "dan": 9,
     "loi": "Lập trường trung thực trước một câu hỏi chưa ngã ngũ là nêu rõ bằng chứng ủng hộ điều gì, không ủng hộ điều gì, và vì sao những người nghiêm túc vẫn bất đồng."
    },
    {
     "ng": "IV",
     "ngTen": "Nhà Thương · Chữ Viết, Đồng Khí và Tế Tự",
     "id": 73,
     "ten": "Chữ Giáp Cốt — Tri Thức Được Ghi Lại",
     "dan": 15,
     "loi": "Văn minh bắt đầu khi tri thức sống sót sau cái chết người tạo ra. Chữ viết là sự bất tử đầu tiên."
    },
    {
     "ng": "V",
     "ngTen": "Nhà Chu · Thiên Mệnh, Lễ Nhạc và Bách Gia",
     "id": 119,
     "ten": "Khổng Tử — Nho Giáo",
     "dan": 21,
     "loi": "Một người thầy tự nhận chỉ truyền lại chứ không sáng tạo rốt cuộc lại sáng tạo nhiều hơn gần như bất kỳ ai — bởi việc truyền lại làm một cách nghiêm túc tự nó là một hành vi chọn lọc và phán xét."
    },
    {
     "ng": "VI",
     "ngTen": "Tần & Hán · Thống Nhất và Đế Chế",
     "id": 159,
     "ten": "Con Đường Tơ Lụa — Dòng Chảy Đông Tây",
     "dan": 21,
     "loi": "Không thương nhân nào từng đi hết con đường — hàng hóa di chuyển theo hình thức tiếp sức qua hàng chục bàn tay, và đó là lý do các ý tưởng đi cùng chúng đến nơi ở dạng đã biến đổi chứ không nguyên vẹn."
    },
    {
     "ng": "VII",
     "ngTen": "Tam Quốc · Lưỡng Tấn Nam Bắc Triều · Phật Giáo Du Nhập",
     "id": 188,
     "ten": "Phật Giáo Du Nhập & Hán Hóa",
     "dan": 17,
     "loi": "Một tôn giáo ngoại lai đi vào không qua sự cải đạo mà qua sự phiên dịch — và ai chọn từ bản địa nào để dịch khái niệm ngoại lai nào thì người đó đã lặng lẽ viết lại tôn giáo ấy."
    },
    {
     "ng": "VIII",
     "ngTen": "Tùy & Đường · Thời Hoàng Kim",
     "id": 223,
     "ten": "An Sử Chi Loạn — Vết Gãy Nhà Đường",
     "dan": 20,
     "loi": "Một cuộc nổi loạn mà một triều đại sống sót qua vẫn có thể chấm dứt nó — nhà Đường tồn tại thêm 150 năm và không bao giờ hồi phục, đó là một kiểu thất bại khác với sự sụp đổ."
    },
    {
     "ng": "IX",
     "ngTen": "Tống · Nguyên · Minh · Thanh",
     "id": 265,
     "ten": "Tam Quốc Diễn Nghĩa — Nghĩa và Mưu",
     "dan": 14,
     "loi": "Một cuốn tiểu thuyết mở đầu bằng \"hợp lâu tất chia, chia lâu tất hợp\" đã nêu luận đề của nó trong một dòng — và dòng đó trở thành cách một nền văn minh kể lại chính lịch sử của mình."
    },
    {
     "ng": "X",
     "ngTen": "Đứt Gãy · The Great Rupture",
     "id": 299,
     "ten": "Cái Đã Mất — Kiểm Kê Một Cách Trung Thực",
     "dan": 18,
     "loi": "Một bản kiểm kê trung thực về những gì một thảm họa đã hủy diệt không phải hành động quy tội — đó là điều kiện tiên quyết để biết còn thứ gì cần được phục hồi."
    },
    {
     "ng": "XI",
     "ngTen": "Phục Hưng và Chuyên Khảo Văn Minh",
     "id": 303,
     "ten": "Cơn Sốt Văn Hóa — Tìm Lại Căn Cước",
     "dan": 13,
     "loi": "Điều đầu tiên một xã hội làm khi được phép tư duy trở lại là hỏi mình đã là ai trước khi dừng lại — các câu hỏi về căn cước nổi lên ngay khi các câu hỏi về sinh tồn lùi đi."
    },
    {
     "ng": "XII",
     "ngTen": "Vùng Miền & Các Dân Tộc Trung Hoa",
     "id": 335,
     "ten": "Tây Vực — Ngã Tư Văn Minh",
     "dan": 17,
     "loi": "Những ý tưởng phong phú nhất thường không đến từ trung tâm lan ra, mà từ rìa đi vào — được mang theo bởi bất cứ ai dám vượt sa mạc."
    },
    {
     "ng": "XIII",
     "ngTen": "Chuyên Khảo Kinh Điển & Tư Tưởng Sâu",
     "id": 350,
     "ten": "Thiền Tông — Phật Giáo Hóa Trung Hoa",
     "dan": 15,
     "loi": "Một ý tưởng du nhập bén rễ sâu nhất không phải khi được giữ nguyên không đổi, mà khi nó hòa quyện hoàn toàn vào đất bản địa đến mức người ta quên rằng nó từng ngoại lai."
    },
    {
     "ng": "XIV",
     "ngTen": "Khoa Học, Kỹ Thuật & Y Học Cổ Truyền",
     "id": 359,
     "ten": "Trung Y — Hệ Thống Tư Duy Âm Dương Ngũ Hành",
     "dan": 15,
     "loi": "Một hệ thống y học xây trên khuôn mẫu và cân bằng, không phải cơ chế biệt lập, đặt câu hỏi khác với \"cái gì đã hỏng\" — nó hỏi \"cái gì đã mất hài hòa.\""
    },
    {
     "ng": "XV",
     "ngTen": "Nghệ Thuật, Kiến Trúc & Thẩm Mỹ",
     "id": 367,
     "ten": "Đồ Sứ — Từ Đất Sét Đến Ngôn Ngữ Thế Giới",
     "dan": 11,
     "loi": "Khi bí quyết kỹ thuật của một nghề thực sự khó sao chép, chính vật phẩm trở thành thương hiệu của nền văn minh — thế giới thực sự đặt tên vật liệu theo quốc gia xuất xứ của nó."
    },
    {
     "ng": "XVI",
     "ngTen": "Phong Tục, Lễ Hội & Đời Sống Dân Gian",
     "id": 379,
     "ten": "Khoa Cử — Con Đường Học Vấn Lên Quan Trường",
     "dan": 28,
     "loi": "Một kỳ thi trọng dụng nhân tài, về lý thuyết mở cho bất kỳ thường dân nào chịu học, là một trong những cỗ máy dịch chuyển xã hội mạnh mẽ nhất mà một nền văn minh tiền hiện đại có thể xây — và cũng là một trong những cỗ máy khắc nghiệt nhất."
    },
    {
     "ng": "XVII",
     "ngTen": "Hải Ngoại & Trung Hoa Đương Đại",
     "id": 385,
     "ten": "Quốc Học Nhiệt — Truyền Thống Trở Lại Trường Học",
     "dan": 16,
     "loi": "Một truyền thống gần như bị chính hậu duệ của nó xóa bỏ (Ch.296, Ch.297, Ch.298) có thể được chủ động dạy lại một thế hệ sau — nhưng phiên bản quay trở lại luôn được biên tập, không bao giờ là bản sao chính xác của những gì đã bị hủy diệt."
    }
   ],
