   "hoc": [
    {
     "ng": "I",
     "ngTen": "Mythic Age · Khai Thiên và Trật Tự Asha",
     "id": 1,
     "ten": "Ahura Mazda — Đấng Minh Triết Tối Cao",
     "dan": 4,
     "loi": "Ahura Mazda là điểm khởi đầu triết học của toàn bộ nền văn minh Ba Tư — mọi vương triều Ba Tư sau này (Achaemenid, Sasanian) đều viện dẫn \"ý chí của Ahura Mazda\" để hợp pháp hóa quyền lực hoàng gia, biến khái niệm thần học này thành nền tảng chính trị-tư tưởng xuyên suốt lịch sử Iran."
    },
    {
     "ng": "II",
     "ngTen": "Elam & Iranian Plateau · Những Nền Móng Trước Ba Tư",
     "id": 25,
     "ten": "Susa — Thành Phố Cổ Của Elam",
     "dan": 2,
     "loi": "Susa minh chứng cho tính liên tục hiếm có của lịch sử Iran — một thành phố có thể phục vụ vai trò trung tâm quyền lực qua nhiều nền văn minh kế tiếp nhau trong hơn 2.000 năm."
    },
    {
     "ng": "III",
     "ngTen": "Median Kingdom · Vương Quốc Mede",
     "id": 41,
     "ten": "Deioces — Vị Vua Đầu Tiên Trong Truyền Thống",
     "dan": 1,
     "loi": "Trường hợp Deioces là bài học kinh điển về phương pháp sử học: cần phân biệt rõ ràng giữa \"truyền thuyết lập quốc\" được các sử gia cổ đại ghi lại và bằng chứng khảo cổ-văn bản đương thời — một nguyên tắc Certainty Labeling quan trọng xuyên suốt Hub này."
    },
    {
     "ng": "IV",
     "ngTen": "Achaemenid Empire · Đế Chế Ba Tư Vĩ Đại",
     "id": 49,
     "ten": "Cyrus Đại Đế — Người Khai Lập Đế Chế",
     "dan": 3,
     "loi": "Cyrus Đại Đế được xem là một trong những nhà lãnh đạo chính trị-quân sự có ảnh hưởng nhất lịch sử nhân loại — mô hình đế chế đa văn hóa, khoan dung tôn giáo của ông sẽ ảnh hưởng đến tư tưởng quản trị đế chế trong hàng ngàn năm sau."
    },
    {
     "ng": "V",
     "ngTen": "Hellenistic Iran · Seleucid và Giao Thoa Đông Tây",
     "id": 96,
     "ten": "Alexander Tại Iran",
     "dan": 2,
     "loi": "Chính sách của Alexander tại Iran là minh chứng cho nhận thức chính trị tinh vi của ông — hiểu rằng việc chinh phục quân sự chỉ là bước đầu, còn việc quản trị lâu dài đòi hỏi sự dung hợp văn hóa và hợp tác với các thế lực địa phương."
    },
    {
     "ng": "VI",
     "ngTen": "Parthian Empire · Đế Quốc Arsacid",
     "id": 110,
     "ten": "Arsaces I — Người Khai Lập",
     "dan": 3,
     "loi": "Việc tên Arsaces trở thành tước hiệu chung cho tất cả các vua Parthia kế tiếp (tương tự \"Caesar\" trong La Mã) phản ánh tầm quan trọng biểu tượng đặc biệt của người sáng lập triều đại này trong ý thức chính trị Parthia."
    },
    {
     "ng": "VII",
     "ngTen": "Sasanian Empire · Phục Hưng Iran Cổ Điển",
     "id": 132,
     "ten": "Ardashir I — Người Khai Lập",
     "dan": 3,
     "loi": "Ardashir I được xem là một trong những nhà cải cách chính trị-tôn giáo vĩ đại nhất lịch sử Iran — đế chế ông sáng lập sẽ tồn tại hơn 400 năm và để lại di sản văn hóa-tôn giáo-nghệ thuật sâu sắc nhất trong toàn bộ lịch sử Ba Tư cổ điển."
    },
    {
     "ng": "VIII",
     "ngTen": "Islamic Conquest & Persian Renaissance · Hồi Giáo Hóa và Ba Tư Hóa",
     "id": 171,
     "ten": "Iran Dưới Các Caliphate",
     "dan": 3,
     "loi": "Giai đoạn đầu dưới các Caliphate đặt nền móng cho một trong những câu chuyện văn minh phức tạp và nghịch lý nhất trong lịch sử: một dân tộc bị chinh phục về chính trị nhưng cuối cùng \"chinh phục ngược\" nền văn minh của kẻ chinh phục về mặt văn hóa-tri thức."
    },
    {
     "ng": "IX",
     "ngTen": "Seljuk & Mongol Iran · Đế Chế Thảo Nguyên và Đại Biến Động",
     "id": 202,
     "ten": "Tughril Beg",
     "dan": 2,
     "loi": "Sự trỗi dậy của Tughril Beg đánh dấu một chương mới trong lịch sử Iran — lần đầu tiên kể từ cuộc chinh phục Ả Rập, một thế lực quân sự du mục mới (Turk) thay thế vai trò thống trị của các triều đại Iran-Ả Rập trước đó."
    },
    {
     "ng": "X",
     "ngTen": "Safavid Iran · Nhà Nước Shi&#x27;a và Thời Hoàng Kim Isfahan",
     "id": 236,
     "ten": "Shah Ismail I",
     "dan": 4,
     "loi": "Shah Ismail I là một trong những nhân vật có ảnh hưởng địa chính trị-tôn giáo lâu dài nhất trong lịch sử Iran — quyết định quốc giáo hóa Shia của ông tiếp tục định hình bản sắc và chính trị Iran hơn năm thế kỷ sau."
    },
    {
     "ng": "XI",
     "ngTen": "Afsharid, Zand & Qajar · Đế Chế, Phân Mảnh và Hiện Đại Hóa",
     "id": 267,
     "ten": "Nader Shah",
     "dan": 2,
     "loi": "Nader Shah được nhiều sử gia gọi là \"Napoleon của Ba Tư\" — một thiên tài quân sự có khả năng khôi phục sức mạnh đế chế Iran từ đống tro tàn của sự sụp đổ Safavid, dù di sản chính trị của ông sẽ không bền vững lâu dài."
    },
    {
     "ng": "XII",
     "ngTen": "Pahlavi Iran · Quốc Gia Hóa, Dầu Mỏ và Cách Mạng",
     "id": 302,
     "ten": "Reza Shah Pahlavi",
     "dan": 3,
     "loi": "Reza Shah Pahlavi là một trong những nhân vật có ảnh hưởng nhất trong lịch sử Iran hiện đại — người sáng lập triều đại cuối cùng trước Cộng Hòa Hồi Giáo, với di sản hiện đại hóa vừa được ca ngợi vừa gây tranh cãi."
    },
    {
     "ng": "XIII",
     "ngTen": "Islamic Republic · Chiến Tranh, Cải Cách và Xã Hội Đương Đại",
     "id": 338,
     "ten": "Velayat-e Faqih — Giám Hộ Của Giáo Luật Gia",
     "dan": 4,
     "loi": "Velayat-e faqih là một trong những đóng góp lý thuyết chính trị-tôn giáo có ảnh hưởng nhất của thế kỷ XX — một mô hình nhà nước thần quyền hiện đại độc đáo, khác biệt hoàn toàn với cả các nền dân chủ thế tục lẫn các chế độ quân chủ Hồi giáo truyền thống."
    },
    {
     "ng": "XIV",
     "ngTen": "Persian Culture · Thi Ca, Nghệ Thuật và Di Sản Sống",
     "id": 371,
     "ten": "Tiếng Ba Tư — Dari, Farsi và Tajik",
     "dan": 2,
     "loi": "Tiếng Ba Tư là một trong những di sản văn hóa bền vững và có ảnh hưởng rộng lớn nhất của nền văn minh Ba Tư — một ngôn ngữ đã tồn tại và thích ứng qua hơn một thiên niên kỷ biến động chính trị."
    }
   ],
