   "hoc": [
    {
     "ng": "I",
     "ngTen": "Mythic Age · Khai Sinh Vũ Trụ và Thần Điện Hy Lạp",
     "id": 20,
     "ten": "Athena — Trí Tuệ và Chiến Lược",
     "dan": 11,
     "loi": "Athena thiết lập một trong những Waterfall Connection thần thoại-lịch sử quan trọng nhất Hub này — một bài học về việc mối liên kết giữa một vị thần và một thành phố cụ thể không chỉ là chi tiết trang trí mà thường phản ánh-củng cố trực tiếp bản sắc-giá trị chính trị mà thành phố đó sẽ theo đuổi trong suốt lịch sử của nó."
    },
    {
     "ng": "II",
     "ngTen": "Aegean Bronze Age · Minoan và Mycenaean",
     "id": 57,
     "ten": "Achilles — Anh Hùng và Cơn Thịnh Nộ",
     "dan": 7,
     "loi": "Achilles mang lại một trong những bài học văn học-triết học sâu sắc nhất về xung đột giữa cái tôi cá nhân và nghĩa vụ tập thể — một bài học về việc ngay cả những xã hội anh hùng tôn vinh danh dự cá nhân cao độ nhất vẫn phải đối mặt với căng thẳng cố hữu khi danh dự cá nhân đó xung đột với lợi ích tập thể, một chủ đề chính trị sẽ tiếp tục được khám phá khi Hy Lạp cổ điển phát triển các mô hình chính trị mới nhấn mạnh lợi ích cộng đồng hơn (forward-link…"
    },
    {
     "ng": "III",
     "ngTen": "Greek Dark Age · Đứt Gãy và Tái Sinh",
     "id": 69,
     "ten": "Homer — Thi Sĩ Của Iliad và Odyssey",
     "dan": 10,
     "loi": "Homer mở đầu Phase với một trong những bài học phương pháp luận quan trọng nhất về bản chất của \"tác giả\" trong văn hóa cổ đại — một bài học về việc nhiều kiệt tác văn học vĩ đại nhất của nhân loại không phải là sản phẩm của một cá nhân sáng tạo cô lập mà là kết tinh của một quá trình tích lũy văn hóa tập thể qua nhiều thế hệ, một khái niệm về \"tác quyền\" khác biệt căn bản so với quan niệm hiện đại về sáng tạo cá nhân."
    },
    {
     "ng": "IV",
     "ngTen": "Archaic Greece · Thành Bang, Luật và Thuộc Địa",
     "id": 111,
     "ten": "Thales — Nước Là Nguyên Lý",
     "dan": 12,
     "loi": "Thales mở đầu một trong những bước ngoặt trí tuệ quan trọng nhất toàn bộ Hub này — một bài học về sự chuyển đổi từ mythos sang logos, đồng thời một bài học certainty quan trọng về việc phần lớn hiểu biết của chúng ta về các triết gia sơ khai nhất chỉ đến qua các nguồn gián tiếp viết nhiều thế kỷ sau, đòi hỏi sự thận trọng học thuật tương tự đã áp dụng cho các nhân vật bán huyền thoại khác trong Hub này (như Lycurgus, Ch.086)."
    },
    {
     "ng": "V",
     "ngTen": "Persian Wars · Tự Do Thành Bang và Cuộc Đối Đầu Đế Chế",
     "id": 130,
     "ten": "Liên Minh Delos",
     "dan": 12,
     "loi": "Liên Minh Delos mở đầu Phase với việc gieo mầm cho một trong những throughline chính trị quan trọng nhất sẽ định hình toàn bộ Epoch VI-VII sắp tới — một bài học về việc các liên minh phòng thủ, dù bắt đầu với ý định tự nguyện-bình đẳng, thường có xu hướng tự nhiên biến đổi thành cấu trúc quyền lực bất cân xứng theo thời gian khi một thành viên có sức mạnh vượt trội, một mô thức chính trị phổ quát sẽ tiếp tục xuất hiện trong lịch sử các liên minh quốc…"
    },
    {
     "ng": "VI",
     "ngTen": "Classical Athens · Dân Chủ, Triết Học và Nghệ Thuật",
     "id": 136,
     "ten": "Ekklesia — Đại Hội Công Dân",
     "dan": 14,
     "loi": "Ekklesia mở đầu Epoch VI với việc hiện thực hóa đầy đủ throughline dân chủ đã phát triển từ Ch.093-098 — một bài học về việc lý tưởng chính trị (dân chủ trực tiếp) khi được thực hành liên tục qua nhiều thập kỷ trở thành một thực tiễn xã hội sống động, không chỉ là một khái niệm lý thuyết, một minh chứng cho khả năng của các thể chế chính trị trưởng thành-tự củng cố theo thời gian."
    },
    {
     "ng": "VII",
     "ngTen": "Peloponnesian War · Nội Chiến và Khủng Hoảng Thành Bang",
     "id": 189,
     "ten": "Cuộc Viễn Chinh Sicily",
     "dan": 5,
     "loi": "Cuộc Viễn Chinh Sicily mang lại một trong những bài học chiến lược-đạo đức quan trọng nhất toàn bộ Hub này — một bài học về \"overreach\" đế chế (tham vọng vượt quá khả năng thực tế), một mô thức lịch sử sẽ tiếp tục lặp lại qua nhiều đế chế khác trong lịch sử nhân loại, một minh chứng cho việc thành công quân sự-chính trị trước đó có thể tạo ra sự tự tin thái quá dẫn đến những quyết định liều lĩnh gây hậu quả thảm khốc."
    }
   ],
