   "hoc": [
    {
     "ng": "I",
     "ngTen": "Mythic Age · Khai Sinh Rome và Dòng Máu Thần Thoại",
     "id": 1,
     "ten": "Aeneas — Người Sống Sót Sau Thành Troy",
     "dan": 0,
     "loi": "Aeneas là mắt xích đầu tiên trong chuỗi phả hệ thần thoại nối liền thành Troy sụp đổ với sự ra đời của Rome — biến câu chuyện khởi nguyên La Mã thành một phần mở rộng của thần thoại Hy Lạp, đồng thời khẳng định nguồn gốc thần thánh (qua Venus) của dân tộc La Mã."
    },
    {
     "ng": "II",
     "ngTen": "Roman Kingdom · Thời Kỳ Bảy Vị Vua",
     "id": 27,
     "ten": "Romulus — Vị Vua Đầu Tiên",
     "dan": 0,
     "loi": "Romulus với tư cách vị vua đầu tiên đặt nền móng cho hai thiết chế sẽ tồn tại xuyên suốt lịch sử La Mã: Senate (trung tâm quyền lực chính trị) và sự phân tầng Patrician/Plebeian (trục xung đột xã hội chính)."
    },
    {
     "ng": "III",
     "ngTen": "Early Republic · Cộng Hòa Sơ Kỳ và Đấu Tranh Giai Cấp",
     "id": 51,
     "ten": "Consul — Hai Người Đồng Chấp Chính",
     "dan": 0,
     "loi": "Consul là biểu tượng chế độ của toàn bộ nền Cộng hòa La Mã — cơ chế phân quyền và giới hạn nhiệm kỳ của nó phản ánh trực tiếp bài học từ sự sụp đổ của chế độ quân chủ."
    },
    {
     "ng": "IV",
     "ngTen": "Punic Wars · Rome Trở Thành Cường Quốc Địa Trung Hải",
     "id": 79,
     "ten": "Sicily — Chiến Trường Đầu Tiên",
     "dan": 0,
     "loi": "Sicily đánh dấu điểm khởi đầu của một trong những cuộc đối đầu địa chính trị quan trọng nhất lịch sử cổ đại — biến Rome từ một cường quốc khu vực Ý thành một thế lực buộc phải học cách thống trị cả trên biển lẫn trên bộ."
    },
    {
     "ng": "V",
     "ngTen": "Late Republic · Khủng Hoảng, Cải Cách và Nội Chiến",
     "id": 110,
     "ten": "Latifundia — Đại Điền Trang",
     "dan": 0,
     "loi": "Latifundia là nguyên nhân kinh tế gốc rễ của toàn bộ cuộc khủng hoảng xã hội sẽ định hình phần lớn lịch sử chính trị của nền Cộng hòa La Mã hậu kỳ."
    },
    {
     "ng": "VI",
     "ngTen": "Augustan Age · Hòa Bình, Trật Tự và Tuyên Ngôn Đế Chế",
     "id": 155,
     "ten": "Princeps — Công Dân Thứ Nhất",
     "dan": 0,
     "loi": "\"Princeps\" là ví dụ kinh điển của nghệ thuật chính trị ngôn từ — cách đặt tên cho quyền lực có thể quyết định sự tồn vong chính trị của người nắm giữ nó, một bài học Augustus đã học được sâu sắc từ chính số phận của cha nuôi mình."
    },
    {
     "ng": "VII",
     "ngTen": "Julio-Claudian & Flavian · Triều Đại, Khủng Hoảng và Colosseum",
     "id": 188,
     "ten": "Tiberius",
     "dan": 0,
     "loi": "Triều đại Tiberius minh họa cho một vấn đề cấu trúc sẽ tái diễn nhiều lần trong lịch sử Đế chế: khi hoàng đế xa rời trung tâm quyền lực, khoảng trống đó luôn được lấp đầy bởi những nhân vật đầy tham vọng khác, thường với hậu quả bất ổn."
    },
    {
     "ng": "VIII",
     "ngTen": "Five Good Emperors · Đỉnh Cao Đế Chế",
     "id": 214,
     "ten": "Nerva",
     "dan": 0,
     "loi": "Nerva, dù triều đại cá nhân không nổi bật, để lại di sản có ảnh hưởng sâu rộng nhất trong toàn bộ lịch sử Đế chế La Mã: khởi động hệ thống kế vị bằng nhận con nuôi sẽ mang lại gần một thế kỷ ổn định chưa từng có."
    },
    {
     "ng": "IX",
     "ngTen": "Crisis of the Third Century · Nội Chiến, Dịch Bệnh và Phân Rã",
     "id": 249,
     "ten": "Commodus",
     "dan": 0,
     "loi": "Cái chết của Commodus là điểm khởi đầu chính thức của một trong những thế kỷ bất ổn nhất trong lịch sử La Mã — lặp lại và làm trầm trọng thêm chính vấn đề cấu trúc đã từng xuất hiện sau Nero."
    },
    {
     "ng": "X",
     "ngTen": "Constantine & Christian Empire · Chuyển Đổi Tôn Giáo và Thủ Đô",
     "id": 278,
     "ten": "Constantine Đại Đế",
     "dan": 0,
     "loi": "Constantine là một trong số ít cá nhân trong lịch sử có thể được coi là đã thay đổi hoàn toàn quỹ đạo của cả một nền văn minh — quyết định của ông về tôn giáo và địa lý chính trị sẽ định hình thế giới trong hơn một thiên niên kỷ."
    },
    {
     "ng": "XI",
     "ngTen": "Fall of the Western Empire · Rome Sụp Đổ ở Phương Tây",
     "id": 305,
     "ten": "Người Goth",
     "dan": 0,
     "loi": "Người Goth là dân tộc có vai trò trung tâm nhất trong toàn bộ câu chuyện về sự sụp đổ của Đế chế Tây La Mã — từ những người tị nạn tuyệt vọng đến những kẻ chinh phục chính thành Rome."
    },
    {
     "ng": "XII",
     "ngTen": "Eastern Roman Empire · Byzantine và Di Sản La Mã Tiếp Nối",
     "id": 329,
     "ten": "Justinian I",
     "dan": 0,
     "loi": "Justinian là một trong những hoàng đế có tầm nhìn xa và tham vọng lớn nhất trong lịch sử Byzantine — di sản của ông (đặc biệt luật pháp) sẽ tồn tại lâu dài hơn nhiều so với các thành tựu lãnh thổ tạm thời của ông."
    },
    {
     "ng": "XIII",
     "ngTen": "Roman Legacy · Luật, Kỹ Thuật, Ngôn Ngữ và Thế Giới Hậu La Mã",
     "id": 348,
     "ten": "Luật La Mã",
     "dan": 0,
     "loi": "Luật La Mã là một trong những di sản trí tuệ bền vững nhất trong lịch sử nhân loại — minh chứng cho việc các sản phẩm tư duy có thể tồn tại và tiếp tục có ảnh hưởng sâu rộng hàng nghìn năm sau khi nền văn minh sản sinh ra chúng đã sụp đổ."
    },
    {
     "ng": "XIV",
     "ngTen": "Rediscovery & Living Rome · Khảo Cổ, Phục Hưng và Ký Ức Toàn Cầu",
     "id": 398,
     "ten": "Renaissance — Phục Hưng Cổ Điển",
     "dan": 0,
     "loi": "Phục Hưng là bước ngoặt văn hóa quan trọng nhất khởi động toàn bộ mối quan tâm hiện đại đối với di sản La Mã cổ đại — nền tảng cho tất cả các phát triển tiếp theo trong Epoch XIV này."
    }
   ],
