   "hoc": [
    {
     "ng": "I",
     "ngTen": "Mythic Oceania · Đại Dương Thiêng",
     "id": 1,
     "ten": "Te Kore — Khoảng Không Nguyên Thủy",
     "dan": 3,
     "loi": "Te Kore là điểm khởi đầu triết học của toàn bộ Hub Oceania Civilizations — một khái niệm về tiềm năng-trước-hình-thể mà nhiều nhà tư tưởng hiện đại so sánh với các khái niệm vật lý-triết học về \"chân không lượng tử\" hay trạng thái tiền-vũ-trụ."
    },
    {
     "ng": "II",
     "ngTen": "First Peoples · Những Người Đầu Tiên Đến Sahul",
     "id": 31,
     "ten": "Sahul — Lục Địa Australia–New Guinea",
     "dan": 2,
     "loi": "Khái niệm Sahul là nền tảng địa chất-địa lý thiết yếu để hiểu toàn bộ câu chuyện định cư sớm nhất của con người tại khu vực này — không phải hai lục địa riêng biệt mà một không gian sinh thái-di cư thống nhất."
    },
    {
     "ng": "III",
     "ngTen": "Lapita Horizon · Những Nhà Hàng Hải Đầu Tiên",
     "id": 59,
     "ten": "Sự Mở Rộng Austronesian",
     "dan": 1,
     "loi": "Sự mở rộng Austronesian là một trong những sự kiện di cư-ngôn ngữ có ảnh hưởng sâu rộng nhất trong lịch sử loài người, định hình bản sắc ngôn ngữ-văn hóa của hàng trăm triệu người từ Madagascar đến Đảo Phục Sinh."
    },
    {
     "ng": "IV",
     "ngTen": "Melanesian Worlds · Thế Giới Melanesia",
     "id": 86,
     "ten": "Nông Nghiệp Cao Nguyên New Guinea",
     "dan": 2,
     "loi": "Nông nghiệp cao nguyên New Guinea là một trong những nền tảng kinh tế bền vững nhất của Melanesia, tiếp tục nuôi sống các cộng đồng cao nguyên đến ngày nay."
    },
    {
     "ng": "V",
     "ngTen": "Micronesian Networks · Các Đế Chế Đảo Nhỏ",
     "id": 116,
     "ten": "Người Chamorro",
     "dan": 1,
     "loi": "Người Chamorro đại diện cho một trong những cuộc định cư sớm nhất và xa nhất của làn sóng mở rộng Austronesian vào Thái Bình Dương, mở đầu cho toàn bộ chương Micronesian Networks của Hub."
    },
    {
     "ng": "VI",
     "ngTen": "Polynesian Triangle · Tam Giác Polynesia",
     "id": 144,
     "ten": "Samoa",
     "dan": 1,
     "loi": "Samoa, cùng với Tonga, tiếp tục là một trong hai trung tâm văn hóa-lịch sử quan trọng nhất của tây Polynesia."
    },
    {
     "ng": "VII",
     "ngTen": "Wayfinding · Nghệ Thuật Tìm Đường Trên Đại Dương",
     "id": 195,
     "ten": "Hōkūleʻa",
     "dan": 1,
     "loi": "Chapter này khép lại phase về các nhân vật sáng lập phong trào phục hưng wayfinding, với Hōkūleʻa là biểu tượng vật chất-tinh thần trung tâm của toàn bộ phong trào."
    },
    {
     "ng": "VIII",
     "ngTen": "Australia Aboriginal Civilizations · Các Nền Văn Minh Country",
     "id": 204,
     "ten": "Các Quốc Gia Bản Địa Australia",
     "dan": 1,
     "loi": "Các quốc gia bản địa Australia đại diện cho một trong những hệ thống đa dạng văn hóa-chính trị phong phú và lâu đời nhất còn tồn tại trên Trái Đất."
    },
    {
     "ng": "IX",
     "ngTen": "Society, Exchange & Sacred Power · Xã Hội Đảo",
     "id": 235,
     "ten": "Các Xã Hội Tù Trưởng",
     "dan": 1,
     "loi": "Chapter này thiết lập khung phân tích cho toàn bộ Epoch IX, cho phép hiểu sâu hơn về hệ thống mana-tapu sẽ được khai triển trong các chapter tiếp theo."
    },
    {
     "ng": "X",
     "ngTen": "European Contact · Những Cuộc Gặp Gỡ Đầu Tiên",
     "id": 267,
     "ten": "Ferdinand Magellan",
     "dan": 1,
     "loi": "Magellan mở đầu cho một chương hoàn toàn mới trong lịch sử Oceania — sự tiếp xúc với thế giới bên ngoài sẽ định hình sâu sắc mọi khía cạnh của khu vực trong các thế kỷ tiếp theo."
    },
    {
     "ng": "XI",
     "ngTen": "Colonial Oceania · Đế Quốc và Định Cư",
     "id": 293,
     "ten": "Australia Thuộc Anh",
     "dan": 1,
     "loi": "Sự thiết lập thuộc địa Anh tại Australia là một trong những sự kiện có tác động biến đổi sâu sắc và lâu dài nhất trong toàn bộ lịch sử Oceania."
    },
    {
     "ng": "XII",
     "ngTen": "World Wars & Nuclear Pacific · Chiến Tranh và Hạt Nhân",
     "id": 323,
     "ten": "Các Thuộc Địa Thái Bình Dương Trong Thế Chiến I",
     "dan": 1,
     "loi": "Chapter này mở đầu Epoch XII, đánh dấu sự lôi kéo Oceania vào các cuộc xung đột toàn cầu của thế kỷ XX."
    },
    {
     "ng": "XIII",
     "ngTen": "Independence & Cultural Revival · Giành Lại Tiếng Nói",
     "id": 350,
     "ten": "Samoa Giành Độc Lập",
     "dan": 1,
     "loi": "Samoa mở đầu Epoch XIII với vai trò tiên phong độc lập, thiết lập tiền lệ quan trọng cho toàn bộ khu vực Thái Bình Dương."
    },
    {
     "ng": "XIV",
     "ngTen": "Living Oceania · Đại Dương Đang Sống",
     "id": 387,
     "ten": "Mực Nước Biển Dâng",
     "dan": 2,
     "loi": "Mực nước biển dâng mở đầu Epoch XIV như thách thức trung tâm định hình tương lai của toàn bộ khu vực Oceania đương đại."
    }
   ],
